46	template <typename T>
47	auto TransformArgs(T&& value)
48	{
49	    static_assert(
50	        std::is_scalar_v<std::decay_t<T>> || Util::IsTensor_v<std::decay_t<T>>,
51	        "TransformArgs only accepts scalar types or Tensor specializations");
52	    if constexpr (std::is_scalar_v<std::decay_t<T>>) {
53	        return std::forward<T>(value);
54	    } else {
55	        return value.GetPtr();
56	    }
57	}
