59	template <class KernelOp, typename OpParam, typename ArgTup>
60	void LaunchKernelWithDataTuple(uint32_t blockNum, aclrtStream& stream, OpParam& cfg, const ArgTup& argTuple)
61	{
62	    static constexpr auto size = std::tuple_size_v<ArgTup>;
63	    auto transformedArgs = std::apply(
64	        [](auto&&... elements) {
65	            return AscendC::Std::make_tuple(TransformArgs(std::forward<decltype(elements)>(elements))...);
66	        },
67	        argTuple);
68	
69	    KernelCustom<KernelOp, OpParam><<<blockNum, nullptr, stream>>>(cfg, transformedArgs);
70	}
