72	/*!
73	 * DeviceAdapter: DeviceAdapter is a generic adapter that provides a host-side generic interface for different operator
74	 * invacation. It encapsulates Acl-related resource management internally and automatically handles kernel invocation.
75	 */
76	template <typename KernelOp>
77	class DeviceAdapter {
78	public:
79	    using ExprMaker = typename KernelOp::ScheduleClz::ExprMaker;
80	    using BlockOp = typename KernelOp::ScheduleClz::BlockTemplate;
81	    // using KernelParamStruct = typename KernelOp::ScheduleClz::ParamStruct;
82	    // using BlockParamStruct = typename KernelOp::ScheduleClz::BlockTemplate::ScheduleClz::ParamStruct;
83	    using OpParam = typename KernelOp::ScheduleCfgClz;
84	    template <typename T>
85	    using Tensor = DeviceTensor<T>;
86	
87	    /*!
88	     * \brief The constructor interface of DeviceAdapter class.
89	     */
90	    DeviceAdapter() {};
91	
92	    /*!
93	     * \brief The external running interface of DeviceAdapter mainly completes resource initialization,
94	     *        data transfer between host and device, and kernel launch.
95	     * \param[in] arguments
96	     */
97	    template <typename Args>
98	    int64_t Run(const Args& arguments, aclrtStream stream = nullptr)
99	    {
100	        auto expr = ToLinearizerExpr(ExprMaker{}.template Compute<Tensor>());
101	        using Expr = typename decltype(expr)::Type;
102	        using Params = Atvoss::Params_t<Expr>;
103	
104	        auto argTuple = std::get<0>(arguments);
105	        // 1. prepare Param
106	        auto params = PrepareParams<Params>(argTuple);
107	
108	        // 2. calc dynamic param （tiling / worksapce）
109	        OpParam opParam;
110	        if (!CalculateTiling<KernelOp>(arguments, opParam)) {
111	            printf("[ERROR]: [Atvoss][Device] CalcParam failed!\n");
112	            return -1;
113	        }
114	        // 3. kernel launch
115	        auto convertArgs = ConvertArgs<Params>(params, argTuple);
116	#if ATVOSS_DEBUG_MODE == 2
117	        for (auto i = 0; i < 200; i++) { // 200 : profiling run times
118	            LaunchKernelWithDataTuple<KernelOp>(opParam.kernelParam.blockNum, stream, opParam, convertArgs);
119	        }
120	#else
121	        LaunchKernelWithDataTuple<KernelOp>(opParam.kernelParam.blockNum, stream, opParam, convertArgs);
122	#endif
123	        return 0;
124	    }
125	
126	private:
127	    // calc kernel/block tiling and workspace.
128	    template <typename Args>
129	    bool CalcParam(const Args& arguments, OpParam& opParam)
130	    {
131	        if (!KernelOp::ScheduleClz::MakeScheduleConfig(arguments, opParam.kernelParam)) {
132	            printf("[ERROR]: [Atvoss][Device] MakeScheduleConfig for kernel failed!\n");
133	            return false;
134	        }
135	        if (!BlockOp::ScheduleClz::MakeScheduleConfig(arguments, opParam.kernelParam, opParam.blockParam)) {
136	            printf("[ERROR]: [Atvoss][Device] MakeScheduleConfig for block failed!\n");
137	            return false;
138	        }
139	        return true;
140	    }
141	
142	    template <typename Params, typename ParamTup>
143	    auto GetInParams(ParamTup& params)
144	    {
145	        constexpr auto size = Atvoss::Util::Size_v<Params>;
146	        static_assert(
147	            size == std::tuple_size_v<ParamTup>,
148	            "[ERROR]: [Atvoss][Device] Size must match the number of element num in ParamTup!\n");
149	        return GetInParamsImpl<Params>(params, std::make_index_sequence<size>{});
150	    }
151	
152	    template <typename Params, typename ParamTup>
153	    auto GetOutParams(ParamTup& params)
154	    {
155	        constexpr auto size = Atvoss::Util::Size_v<Params>;
156	        static_assert(
157	            size == std::tuple_size_v<ParamTup>,
158	            "[ERROR]: [Atvoss][Device] Size must match the number of element num in ParamTup!\n");
159	        return GetOutParamsImpl<Params>(params, std::make_index_sequence<size>{});
160	    }
161	
162	    template <typename InParams, typename InParamTup, typename ArgTup>
163	    void CopyIn(InParamTup& inParams, ArgTup& args)
164	    {
165	        constexpr auto size = Atvoss::Util::Size_v<InParams>;
166	        static_assert(
167	            size == std::tuple_size_v<InParamTup>,
168	            "[ERROR]: [Atvoss][Device] Size must match the number of element num in InParamTup!\n");
169	        CopyInImpl<InParams>(inParams, args, std::make_index_sequence<size>{});
170	    }
171	
172	    template <typename OutParams, typename OutParamTup, typename ArgTup>
173	    void CopyOut(OutParamTup& outParams, ArgTup& args)
174	    {
175	        constexpr auto size = Atvoss::Util::Size_v<OutParams>;
176	        static_assert(
177	            size == std::tuple_size_v<OutParamTup>,
178	            "[ERROR]: [Atvoss][Device] Size must match the number of element num in OutParamTup!\n");
179	        CopyOutImpl<OutParams>(outParams, args, std::make_index_sequence<size>{});
180	    }
181	
182	    template <typename ParamType, typename ArgTup>
183	    constexpr auto ConstructParam(ArgTup& args)
184	    {
185	        using ArgType = std::decay_t<std::tuple_element_t<ParamType::number - 1, ArgTup>>;
186	        if constexpr (
187	            std::is_scalar_v<typename ParamType::Type> && Atvoss::Util::IsSpecializationOf_v<Atvoss::Tensor, ArgType>) {
188	            return Tensor<typename ParamType::Type>(std::get<ParamType::number - 1>(args));
189	        } else {
190	            return typename std::decay_t<typename ParamType::Type>(std::get<ParamType::number - 1>(args));
191	        }
192	    }
193	
194	    template <typename Params, typename ArgTup, std::size_t... Ints>
195	    constexpr auto PrepareParamsImpl(ArgTup& args, std::index_sequence<Ints...>)
196	    {
197	        return std::make_tuple(ConstructParam<Atvoss::Util::Get_t<Params, Ints>>(args)...);
198	    }
199	
200	    template <typename Params, typename ArgTup>
201	    constexpr auto PrepareParams(ArgTup& argTuple)
202	    {
203	        return PrepareParamsImpl<Params>(argTuple, std::make_index_sequence<Atvoss::Util::Size_v<Params>>{});
204	    }
205	
206	    template <typename Params, std::size_t Index, typename ParamTup, typename ArgTup>
207	    constexpr auto ConvertOneArg(ParamTup& params, ArgTup& args)
208	    {
209	        constexpr auto pos = Atvoss::Util::Find_v<Atvoss::CheckVarNum<Index + 1>::template Checker, Params>;
210	        if constexpr (pos < Atvoss::Util::Size_v<Params>) {
211	            return std::get<pos>(params);
212	        } else {
213	            return std::get<Index>(args);
214	        }
215	    }
216	
217	    template <typename Params, typename ParamTup, typename ArgTup, std::size_t... Ints>
218	    constexpr auto ConvertArgsImpl(ParamTup& params, ArgTup& args, std::index_sequence<Ints...>)
219	    {
220	        return std::make_tuple(ConvertOneArg<Params, Ints>(params, args)...);
221	    }
222	
223	    template <typename Params, typename ParamTup, typename ArgTup>
224	    auto ConvertArgs(ParamTup& params, ArgTup& args)
225	    {
226	        return ConvertArgsImpl<Params>(params, args, std::make_index_sequence<std::tuple_size_v<ArgTup>>{});
227	    }
228	
229	    template <typename Params, std::size_t Index, Atvoss::ParamUsage... usages, typename ParamTup>
230	    constexpr auto GetOneParam(ParamTup& params)
231	    {
232	        using Param = Atvoss::Util::Get_t<Params, Index>;
233	        if constexpr (((Param::usage == usages) || ...)) {
234	            return std::forward_as_tuple(std::get<Index>(params));
235	        } else {
236	            return std::tuple<>{};
237	        }
238	    }
239	
240	    template <typename Params, typename ParamTup, std::size_t... Ints>
241	    constexpr auto GetInParamsImpl(ParamTup& params, std::index_sequence<Ints...>)
242	    {
243	        return std::tuple_cat(GetOneParam<Params, Ints, Atvoss::ParamUsage::IN, Atvoss::ParamUsage::IN_OUT>(params)...);
244	    }
245	
246	    template <typename Params, typename ParamTup, std::size_t... Ints>
247	    constexpr auto GetOutParamsImpl(ParamTup& params, std::index_sequence<Ints...>)
248	    {
249	        return std::tuple_cat(
250	            GetOneParam<Params, Ints, Atvoss::ParamUsage::OUT, Atvoss::ParamUsage::IN_OUT>(params)...);
251	    }
252	
253	    template <typename InParams, std::size_t Index, typename T, typename ArgTup>
254	    void CopyInOneParam(T& param, ArgTup& args)
255	    {
256	        using Param = Atvoss::Util::Get_t<InParams, Index>;
257	        param.CopyIn();
258	    }
259	
260	    template <typename InParams, typename InParamTup, typename ArgTup, std::size_t... Ints>
261	    void CopyInImpl(InParamTup& inParams, ArgTup& args, std::index_sequence<Ints...>)
262	    {
263	        (CopyInOneParam<InParams, Ints>(std::get<Ints>(inParams), args), ...);
264	    }
265	
266	    template <typename OutParams, std::size_t Index, typename T, typename ArgTup>
267	    void CopyOutOneParam(T& param, ArgTup& args)
268	    {
269	        using Param = Atvoss::Util::Get_t<OutParams, Index>;
270	        param.CopyOut();
271	    }
272	
273	    template <typename OutParams, typename OutParamTup, typename ArgTup, std::size_t... Ints>
274	    void CopyOutImpl(OutParamTup& outParams, ArgTup& args, std::index_sequence<Ints...>)
275	    {
276	        (CopyOutOneParam<OutParams, Ints>(std::get<Ints>(outParams), args), ...);
277	    }
278	};
279	
280	} // namespace Atvoss
281	#endif

