16	template <typename KernelOp, typename Args>
17	bool CalculateTiling(const Args& args, typename KernelOp::ScheduleCfgClz& cfg)
18	{
19	    using BlockOp = typename KernelOp::ScheduleClz::BlockTemplate;
20	    if (!KernelOp::ScheduleClz::MakeScheduleConfig(args, cfg.kernelParam)) {
21	        printf("[ERROR]: [Atvoss][Device] MakeScheduleConfig for kernel failed!\n");
22	        return false;
23	    }
24	
25	    if (!BlockOp::ScheduleClz::MakeScheduleConfig(args, cfg.kernelParam, cfg.blockParam)) {
26	        printf("[ERROR]: [Atvoss][Device] MakeScheduleConfig for block failed!\n");
27	        return false;
28	    }
29	    return true;
30	}
