24	    {
25	        ptr_ = src.data();
26	    }
27	
28	    T& operator[](std::size_t pos)
29	    {
30	        return ptr_[pos];
31	    }
32	    const T& operator[](std::size_t pos) const
33	    {
34	        return ptr_[pos];
35	    }
36	
37	    void Clear()
38	    {
39	        if (ptr_ != nullptr) {
40	            delete[] ptr_;
41	            ptr_ = nullptr;
42	        }
43	    }
44	
45	    auto GetPtr() const
46	    {
47	        return ptr_;
48	    }
49	    using IsTensor = void;
50	
51	private:
52	    T* ptr_{nullptr};
53	};
