53	__host_aicore__ constexpr auto PreProcessComputeExpr(const Expression<T>& expr)
54	{
55	    using ExprT = T;
56	    using OriExprList = typename Atvoss::FlattenAtOpAndThen<ExprT>::Type;
57	    static_assert(Size_v<OriExprList> > 0, "Compute expression is empty.");
58	
59	    // 1. Dag
60	    using DagX = typename DagSelector<OriExprList, memMngPolicy>::Type;
61	    // 2. Add OpAlloc before its first use & OpFree after its last use
62	    using ExprListWithCopyX = typename DagX::ExprListWithCopyX;
63	    using ParamUseList = typename DagX::ParamUseList;
64	    using LocalVarUseList = typename DagX::LocalVarUseList;
65	    auto result1 = ForEach(Reverse_t<ParamUseList>{}, Atvoss::Graph::AllocInserter{}, ExprListWithCopyX{});
66	    auto result2 = ForEach(ParamUseList{}, Atvoss::Graph::FreeInserter{}, result1);
67	    auto result3 = ForEach(Reverse_t<LocalVarUseList>{}, Atvoss::Graph::AllocInserter{}, result2);
68	    auto result4 = ForEach(LocalVarUseList{}, Atvoss::Graph::FreeInserter{}, result3);
69	    // 3. Rebuild Expression
70	    using LastExpression = typename BuildExpression<decltype(result4)>::Type;
71	    return ComputeInfo<LastExpression, DagX>{};
72	};
